unsigned int calls=0;
struct Fixture {const char* name;std::uint32_t entry,stop;unsigned int carry;std::uint32_t regs[16];std::uint32_t seed,slots;unsigned int mode;
 const char* puts;const char* error;std::uint32_t out[16];std::uint32_t pc;unsigned int c,nports;std::uint32_t bank,ff8,ff9;unsigned long long digest;};
// One generic block step per incoming C (clear / set): native successor, expected C (contract classification), digest and port count.
struct Block {std::uint32_t pc,next_clear;unsigned int c_clear;unsigned long long digest_clear;unsigned int ports_clear;std::uint32_t next_set;
 unsigned int c_set;unsigned long long digest_set;unsigned int ports_set;std::uint32_t regs[16];};
